export const REAL_NOVA_BOOT_C = "/**\n * ============================================================================\n * NOVA UEFI x64 Boot Manager - Release 1.0 (Production)\n * ============================================================================\n * Architecture : x86_64 UEFI PE32+\n * Cibles       : Dual-Boot macOS (OpenCore sur LDLC F7) & Windows (KXG6A)\n * ============================================================================\n */\n\n#include <efi.h>\n#include <efilib.h>\n#include \"font8x8_basic.h\"\n\n// System choices\ntypedef struct {\n    CHAR16  *Name;\n    CHAR16  *Subtitle;\n    CHAR16  *DeviceHint;\n    CHAR16  *FilePath;\n    BOOLEAN Available;\n    EFI_HANDLE DeviceHandle;\n    EFI_DEVICE_PATH_PROTOCOL *DevicePath;\n} BOOT_TARGET;\n\n#define TARGET_MACOS   0\n#define TARGET_WINDOWS 1\n#define TARGET_COUNT   2\n\nstatic BOOT_TARGET Targets[TARGET_COUNT] = {\n    {\n        L\"macOS Tahoe 26.6\",\n        L\"OpenCore Loader\",\n        L\"Disque LDLC F7 (Volume EFICORE)\",\n        L\"\\\\EFI\\\\OC\\\\OpenCore.efi\",\n        FALSE,\n        NULL,\n        NULL\n    },\n    {\n        L\"Windows 11 Famille Edition\",\n        L\"Windows Boot Manager\",\n        L\"Disque KXG6A (Partition EFI)\",\n        L\"\\\\EFI\\\\Microsoft\\\\Boot\\\\bootmgfw.efi\",\n        FALSE,\n        NULL,\n        NULL\n    }\n};\n\n// Graphics context\nstatic EFI_GRAPHICS_OUTPUT_PROTOCOL *Gop = NULL;\nstatic UINT32 ScreenWidth = 0;\nstatic UINT32 ScreenHeight = 0;\nstatic EFI_GRAPHICS_OUTPUT_BLT_PIXEL *BackBuffer = NULL;\n\n// Palette definitions (Liquid Glass & Dark Slate)\n#define COLOR_BG          0x0B0D14\n#define COLOR_HEADER_BG   0x111624\n#define COLOR_CARD_NORMAL 0x141826\n#define COLOR_CARD_SELECT 0x1E2438\n#define COLOR_BORDER_NORM 0x2A324A\n#define COLOR_BORDER_GOLD 0xF59E0B\n#define COLOR_TEXT_WHITE  0xFFFFFF\n#define COLOR_TEXT_MUTED  0x94A3B8\n#define COLOR_TEXT_AMBER  0xFBBF24\n#define COLOR_TEXT_CYAN   0x38BDF8\n#define COLOR_TEXT_GREEN  0x34D399\n\nstatic inline EFI_GRAPHICS_OUTPUT_BLT_PIXEL MakePixel(UINT32 Rgb) {\n    EFI_GRAPHICS_OUTPUT_BLT_PIXEL P;\n    P.Red = (UINT8)((Rgb >> 16) & 0xFF);\n    P.Green = (UINT8)((Rgb >> 8) & 0xFF);\n    P.Blue = (UINT8)(Rgb & 0xFF);\n    P.Reserved = 0;\n    return P;\n}\n\nstatic void PutPixel(UINT32 X, UINT32 Y, UINT32 Rgb) {\n    if (X >= ScreenWidth || Y >= ScreenHeight || BackBuffer == NULL) return;\n    BackBuffer[Y * ScreenWidth + X] = MakePixel(Rgb);\n}\n\nstatic void FillRect(UINT32 X, UINT32 Y, UINT32 W, UINT32 H, UINT32 Rgb) {\n    if (BackBuffer == NULL) return;\n    UINT32 X2 = (X + W > ScreenWidth) ? ScreenWidth : (X + W);\n    UINT32 Y2 = (Y + H > ScreenHeight) ? ScreenHeight : (Y + H);\n    EFI_GRAPHICS_OUTPUT_BLT_PIXEL P = MakePixel(Rgb);\n\n    for (UINT32 py = Y; py < Y2; py++) {\n        UINT32 Offset = py * ScreenWidth;\n        for (UINT32 px = X; px < X2; px++) {\n            BackBuffer[Offset + px] = P;\n        }\n    }\n}\n\nstatic void DrawRectOutline(UINT32 X, UINT32 Y, UINT32 W, UINT32 H, UINT32 Thickness, UINT32 Rgb) {\n    FillRect(X, Y, W, Thickness, Rgb);\n    FillRect(X, Y + H - Thickness, W, Thickness, Rgb);\n    FillRect(X, Y, Thickness, H, Rgb);\n    FillRect(X + W - Thickness, Y, Thickness, H, Rgb);\n}\n\nstatic void DrawChar(UINT32 X, UINT32 Y, CHAR8 C, UINT32 Color, UINT32 Scale) {\n    if ((UINT8)C > 127) C = '?';\n    const UINT8 *Glyph = (const UINT8*)font8x8_basic[(UINT8)C];\n\n    for (UINT32 row = 0; row < 8; row++) {\n        UINT8 RowBits = Glyph[row];\n        for (UINT32 col = 0; col < 8; col++) {\n            if (RowBits & (1 << col)) {\n                if (Scale == 1) {\n                    PutPixel(X + col, Y + row, Color);\n                } else {\n                    FillRect(X + col * Scale, Y + row * Scale, Scale, Scale, Color);\n                }\n            }\n        }\n    }\n}\n\nstatic void DrawString(UINT32 X, UINT32 Y, const CHAR16 *Str, UINT32 Color, UINT32 Scale) {\n    UINT32 CurX = X;\n    while (*Str) {\n        CHAR8 C = (CHAR8)(*Str & 0x7F);\n        DrawChar(CurX, Y, C, Color, Scale);\n        CurX += 8 * Scale + (Scale > 1 ? 1 : 0);\n        Str++;\n    }\n}\n\nstatic void DrawAppleLogo(UINT32 CX, UINT32 CY, UINT32 Color) {\n    FillRect(CX - 14, CY - 16, 28, 32, Color);\n    FillRect(CX - 19, CY - 10, 38, 20, Color);\n    FillRect(CX - 15, CY - 20, 30, 36, Color);\n    // Bite cutout\n    FillRect(CX + 10, CY - 5, 10, 10, COLOR_CARD_SELECT);\n    // Leaf\n    FillRect(CX - 2, CY - 26, 6, 5, Color);\n}\n\nstatic void DrawWindowsLogo(UINT32 CX, UINT32 CY, UINT32 Color) {\n    UINT32 S = 14;\n    UINT32 Gap = 4;\n    FillRect(CX - S - Gap/2, CY - S - Gap/2, S, S, Color);\n    FillRect(CX + Gap/2,     CY - S - Gap/2, S, S, Color);\n    FillRect(CX - S - Gap/2, CY + Gap/2,     S, S, Color);\n    FillRect(CX + Gap/2,     CY + Gap/2,     S, S, Color);\n}\n\nstatic void RenderScreen(INTN SelectedIndex, UINT32 PulseAnim, const CHAR16 *StatusMsg) {\n    // Fill deep dark canvas\n    FillRect(0, 0, ScreenWidth, ScreenHeight, COLOR_BG);\n\n    // Header bar\n    FillRect(0, 0, ScreenWidth, 50, COLOR_HEADER_BG);\n    DrawRectOutline(0, 48, ScreenWidth, 2, 2, 0x1F293D);\n\n    DrawString(24, 16, L\"NOVA EFI BOOT MANAGER\", COLOR_TEXT_AMBER, 2);\n    DrawString(ScreenWidth - 310, 18, L\"UEFI x64 DirectGOP\", COLOR_TEXT_MUTED, 1);\n\n    // Active resolution banner\n    CHAR16 ResBuf[80];\n    SPrint(ResBuf, sizeof(ResBuf), L\"Mode GOP Actif : %dx%d (Detection automatique)\", ScreenWidth, ScreenHeight);\n    DrawString(24, 64, ResBuf, 0x64748B, 1);\n\n    // Center layout calculations\n    UINT32 CardW = (ScreenWidth >= 800) ? 320 : (ScreenWidth / 2 - 30);\n    UINT32 CardH = 220;\n    UINT32 Spacing = (ScreenWidth >= 800) ? 40 : 16;\n    UINT32 TotalW = 2 * CardW + Spacing;\n    UINT32 StartX = (ScreenWidth > TotalW) ? ((ScreenWidth - TotalW) / 2) : 10;\n    UINT32 CardY = (ScreenHeight > CardH + 140) ? ((ScreenHeight - CardH) / 2 - 10) : 90;\n\n    for (INTN i = 0; i < TARGET_COUNT; i++) {\n        UINT32 X = StartX + i * (CardW + Spacing);\n        BOOLEAN IsSel = (i == SelectedIndex);\n\n        // Card body\n        FillRect(X, CardY, CardW, CardH, IsSel ? COLOR_CARD_SELECT : COLOR_CARD_NORMAL);\n\n        // Border\n        if (IsSel) {\n            UINT32 BorderColor = COLOR_BORDER_GOLD;\n            if (PulseAnim % 16 < 8) BorderColor = 0xFCD34D;\n            DrawRectOutline(X, CardY, CardW, CardH, 2, BorderColor);\n        } else {\n            DrawRectOutline(X, CardY, CardW, CardH, 1, COLOR_BORDER_NORM);\n        }\n\n        // Draw Icon\n        UINT32 IconCX = X + CardW / 2;\n        UINT32 IconCY = CardY + 54;\n        if (i == TARGET_MACOS) {\n            DrawAppleLogo(IconCX, IconCY, IsSel ? 0xFFFFFF : 0x94A3B8);\n        } else {\n            DrawWindowsLogo(IconCX, IconCY, IsSel ? COLOR_TEXT_CYAN : 0x0284C7);\n        }\n\n        // Title\n        DrawString(X + 20, CardY + 104, Targets[i].Name, COLOR_TEXT_WHITE, 2);\n\n        // Subtitle\n        DrawString(X + 20, CardY + 132, Targets[i].Subtitle, IsSel ? COLOR_TEXT_AMBER : COLOR_TEXT_MUTED, 1);\n        DrawString(X + 20, CardY + 152, Targets[i].DeviceHint, 0x64748B, 1);\n\n        // Availability status\n        if (Targets[i].Available) {\n            DrawString(X + 20, CardY + 180, L\"[Chargeur Detecte]\", COLOR_TEXT_GREEN, 1);\n        } else {\n            DrawString(X + 20, CardY + 180, L\"[Recherche de volume...]\", 0xEAB308, 1);\n        }\n\n        // Selection arrow\n        if (IsSel) {\n            DrawString(X + CardW / 2 - 6, CardY + CardH + 12, L\"^\", COLOR_BORDER_GOLD, 2);\n            DrawString(X + CardW / 2 - 34, CardY + CardH + 30, L\"[ENTREE]\", COLOR_TEXT_AMBER, 1);\n        }\n    }\n\n    // Status / Message banner\n    if (StatusMsg != NULL && StatusMsg[0] != L'\\0') {\n        FillRect(StartX, CardY + CardH + 60, TotalW, 32, 0x1E1B4B);\n        DrawRectOutline(StartX, CardY + CardH + 60, TotalW, 32, 1, 0x6366F1);\n        DrawString(StartX + 14, CardY + CardH + 70, StatusMsg, 0xE0E7FF, 1);\n    }\n\n    // Footer Navigation Guide\n    FillRect(0, ScreenHeight - 40, ScreenWidth, 40, COLOR_HEADER_BG);\n    DrawRectOutline(0, ScreenHeight - 41, ScreenWidth, 1, 1, 0x1F293D);\n\n    DrawString(24, ScreenHeight - 25, L\"[<- / ->] Choisir\", 0x94A3B8, 1);\n    DrawString(180, ScreenHeight - 25, L\"[Entree] Demarrer\", COLOR_TEXT_AMBER, 1);\n    DrawString(340, ScreenHeight - 25, L\"[F10] Redemarrer\", 0x94A3B8, 1);\n    DrawString(500, ScreenHeight - 25, L\"[Echap] Eteindre\", 0x94A3B8, 1);\n\n    // Blt buffer to screen\n    Gop->Blt(Gop, BackBuffer, EfiBltBufferToVideo, 0, 0, 0, 0, ScreenWidth, ScreenHeight, ScreenWidth * sizeof(EFI_GRAPHICS_OUTPUT_BLT_PIXEL));\n}\n\n// Search all EFI volumes for the target loader\nstatic void ScanForTargets(void) {\n    UINTN HandleCount = 0;\n    EFI_HANDLE *HandleBuffer = NULL;\n\n    EFI_STATUS Status = uefi_call_wrapper(BS->LocateHandleBuffer, 5,\n        ByProtocol,\n        &gEfiSimpleFileSystemProtocolGuid,\n        NULL,\n        &HandleCount,\n        &HandleBuffer\n    );\n\n    if (EFI_ERROR(Status) || HandleCount == 0) return;\n\n    for (UINTN h = 0; h < HandleCount; h++) {\n        EFI_SIMPLE_FILE_SYSTEM_PROTOCOL *Fs = NULL;\n        Status = uefi_call_wrapper(BS->HandleProtocol, 3,\n            HandleBuffer[h],\n            &gEfiSimpleFileSystemProtocolGuid,\n            (VOID**)&Fs\n        );\n        if (EFI_ERROR(Status) || Fs == NULL) continue;\n\n        EFI_FILE_PROTOCOL *Root = NULL;\n        Status = uefi_call_wrapper(Fs->OpenVolume, 2, Fs, &Root);\n        if (EFI_ERROR(Status) || Root == NULL) continue;\n\n        for (INTN t = 0; t < TARGET_COUNT; t++) {\n            if (Targets[t].Available) continue;\n\n            EFI_FILE_PROTOCOL *File = NULL;\n            CHAR16 *RelPath = Targets[t].FilePath;\n            if (RelPath[0] == L'\\\\') RelPath++;\n\n            Status = uefi_call_wrapper(Root->Open, 5, Root, &File, RelPath, EFI_FILE_MODE_READ, 0);\n            if (!EFI_ERROR(Status) && File != NULL) {\n                uefi_call_wrapper(File->Close, 1, File);\n                Targets[t].Available = TRUE;\n                Targets[t].DeviceHandle = HandleBuffer[h];\n                Targets[t].DevicePath = FileDevicePath(HandleBuffer[h], Targets[t].FilePath);\n            }\n        }\n\n        uefi_call_wrapper(Root->Close, 1, Root);\n    }\n\n    if (HandleBuffer != NULL) {\n        FreePool(HandleBuffer);\n    }\n}\n\n// Chainload target .efi image\nstatic EFI_STATUS LaunchTarget(EFI_HANDLE ParentImage, INTN TargetIndex, CHAR16 **OutError) {\n    if (TargetIndex < 0 || TargetIndex >= TARGET_COUNT) {\n        *OutError = L\"Indice invalide.\";\n        return EFI_INVALID_PARAMETER;\n    }\n\n    BOOT_TARGET *T = &Targets[TargetIndex];\n    if (!T->Available || T->DevicePath == NULL) {\n        *OutError = L\"Fichier EFI introuvable. Verifiez que le disque est connecte.\";\n        return EFI_NOT_FOUND;\n    }\n\n    EFI_HANDLE LoadedImage = NULL;\n    EFI_STATUS Status = uefi_call_wrapper(BS->LoadImage, 6,\n        FALSE,\n        ParentImage,\n        T->DevicePath,\n        NULL,\n        0,\n        &LoadedImage\n    );\n\n    if (EFI_ERROR(Status)) {\n        *OutError = L\"Erreur BS->LoadImage (Verifiez Secure Boot dans le BIOS).\";\n        return Status;\n    }\n\n    UINTN ExitDataSize = 0;\n    CHAR16 *ExitData = NULL;\n    Status = uefi_call_wrapper(BS->StartImage, 3, LoadedImage, &ExitDataSize, &ExitData);\n\n    if (EFI_ERROR(Status)) {\n        *OutError = L\"Erreur BS->StartImage lors du passage de controle.\";\n        return Status;\n    }\n\n    return EFI_SUCCESS;\n}\n\nstatic EFI_SIMPLE_POINTER_PROTOCOL *Pointer = NULL;\n\nstatic void InitPointer(void) {\n    LibLocateProtocol(&SimplePointerProtocol, (VOID**)&Pointer);\n    if (Pointer != NULL) {\n        uefi_call_wrapper(Pointer->Reset, 2, Pointer, FALSE);\n    }\n}\n\nEFI_STATUS\nEFIAPI\nefi_main (EFI_HANDLE ImageHandle, EFI_SYSTEM_TABLE *SystemTable) {\n    InitializeLib(ImageHandle, SystemTable);\n\n    // Disable watchdog\n    uefi_call_wrapper(BS->SetWatchdogTimer, 4, 0, 0, 0, NULL);\n\n    // Locate GOP\n    EFI_STATUS Status = LibLocateProtocol(&GraphicsOutputProtocol, (VOID**)&Gop);\n    if (EFI_ERROR(Status) || Gop == NULL) {\n        Print(L\"NOVA Error: UEFI GOP non disponible.\\n\");\n        return Status;\n    }\n\n    // Attempt 1920x1080 mode or fallback to highest available resolution\n    UINT32 BestMode = Gop->Mode->Mode;\n    UINT32 BestWidth = Gop->Mode->Info->HorizontalResolution;\n\n    for (UINT32 m = 0; m < Gop->Mode->MaxMode; m++) {\n        EFI_GRAPHICS_OUTPUT_MODE_INFORMATION *Info;\n        UINTN SizeOfInfo;\n        Status = Gop->QueryMode(Gop, m, &SizeOfInfo, &Info);\n        if (!EFI_ERROR(Status) && Info != NULL) {\n            if (Info->HorizontalResolution == 1920 && Info->VerticalResolution == 1080) {\n                BestMode = m;\n                BestWidth = 1920;\n                break;\n            } else if (Info->HorizontalResolution > BestWidth && BestWidth != 1920) {\n                BestMode = m;\n                BestWidth = Info->HorizontalResolution;\n            }\n        }\n    }\n\n    if (BestMode != Gop->Mode->Mode) {\n        Gop->SetMode(Gop, BestMode);\n    }\n\n    ScreenWidth = Gop->Mode->Info->HorizontalResolution;\n    ScreenHeight = Gop->Mode->Info->VerticalResolution;\n\n    // Allocate BackBuffer\n    Status = uefi_call_wrapper(BS->AllocatePool, 3,\n        EfiBootServicesData,\n        ScreenWidth * ScreenHeight * sizeof(EFI_GRAPHICS_OUTPUT_BLT_PIXEL),\n        (VOID**)&BackBuffer\n    );\n    if (EFI_ERROR(Status) || BackBuffer == NULL) {\n        Print(L\"NOVA Error: Memoire video insuffisante pour BackBuffer.\\n\");\n        return Status;\n    }\n\n    // Scan for OpenCore and Windows\n    ScanForTargets();\n\n    // Mouse pointer\n    InitPointer();\n\n    INTN Selected = TARGET_MACOS;\n    UINT32 AnimCounter = 0;\n    CHAR16 *StatusMessage = L\"Pret. Selectionnez le systeme a amorcer puis appuyez sur Entree.\";\n\n    // Interactive Loop\n    while (TRUE) {\n        RenderScreen(Selected, AnimCounter++, StatusMessage);\n\n        // Keyboard polling\n        EFI_INPUT_KEY Key;\n        Status = uefi_call_wrapper(SystemTable->ConIn->ReadKeyStroke, 2, SystemTable->ConIn, &Key);\n\n        if (!EFI_ERROR(Status)) {\n            StatusMessage = L\"\";\n\n            if (Key.ScanCode == SCAN_RIGHT || Key.UnicodeChar == L'd' || Key.UnicodeChar == L'D') {\n                Selected = (Selected + 1) % TARGET_COUNT;\n            } else if (Key.ScanCode == SCAN_LEFT || Key.UnicodeChar == L'q' || Key.UnicodeChar == L'Q' || Key.UnicodeChar == L'a') {\n                Selected = (Selected - 1 + TARGET_COUNT) % TARGET_COUNT;\n            } else if (Key.UnicodeChar == CHAR_CARRIAGE_RETURN) {\n                StatusMessage = L\"Chargement du binaire UEFI en cours...\";\n                RenderScreen(Selected, AnimCounter, StatusMessage);\n                CHAR16 *ErrorMsg = NULL;\n                EFI_STATUS LaunchStatus = LaunchTarget(ImageHandle, Selected, &ErrorMsg);\n                if (EFI_ERROR(LaunchStatus)) {\n                    StatusMessage = ErrorMsg ? ErrorMsg : L\"Echec du chargement du chargeur.\";\n                }\n            } else if (Key.ScanCode == SCAN_F10) {\n                uefi_call_wrapper(RT->ResetSystem, 4, EfiResetWarm, EFI_SUCCESS, 0, NULL);\n            } else if (Key.ScanCode == SCAN_ESC) {\n                uefi_call_wrapper(RT->ResetSystem, 4, EfiResetShutdown, EFI_SUCCESS, 0, NULL);\n            }\n        }\n\n        // Pointer polling\n        if (Pointer != NULL) {\n            EFI_SIMPLE_POINTER_STATE PState;\n            Status = uefi_call_wrapper(Pointer->GetState, 2, Pointer, &PState);\n            if (!EFI_ERROR(Status)) {\n                if (PState.LeftButton) {\n                    StatusMessage = L\"Clic enregistre. Lancement de la cible...\";\n                    RenderScreen(Selected, AnimCounter, StatusMessage);\n                    CHAR16 *ErrorMsg = NULL;\n                    LaunchTarget(ImageHandle, Selected, &ErrorMsg);\n                }\n            }\n        }\n\n        // 30ms sleep (~33 fps)\n        uefi_call_wrapper(BS->Stall, 1, 30000);\n    }\n\n    return EFI_SUCCESS;\n}\n";
