export const REAL_MAKEFILE = "CC = gcc\nLD = ld\nOBJCOPY = objcopy\n\nEFIINC = /usr/include/efi\nEFILIB = /usr/lib\n\nCFLAGS = -I$(EFIINC) -I$(EFIINC)/x86_64 -I$(EFIINC)/protocol \\\n         -fpic -ffreestanding -fno-stack-protector -fno-stack-check \\\n         -fshort-wchar -mno-red-zone -maccumulate-outgoing-args \\\n         -Wall -Wextra -O2\n\nLDFLAGS = -shared -Bsymbolic -L$(EFILIB) -T $(EFILIB)/elf_x86_64_efi.lds \\\n          $(EFILIB)/crt0-efi-x86_64.o\n\nall: BOOTX64.EFI\n\nnova_boot.o: nova_boot.c font8x8_basic.h\n\t$(CC) $(CFLAGS) -c nova_boot.c -o nova_boot.o\n\nnova_boot.so: nova_boot.o\n\t$(LD) $(LDFLAGS) nova_boot.o -o nova_boot.so -lgnuefi -lefi\n\nBOOTX64.EFI: nova_boot.so\n\t$(OBJCOPY) -j .text -j .sdata -j .data -j .dynamic -j .dynsym \\\n\t           -j .rel -j .rela -j .rel.* -j .rela.* -j .reloc \\\n\t           --target efi-app-x86_64 --subsystem=10 nova_boot.so BOOTX64.EFI\n\nclean:\n\trm -f *.o *.so BOOTX64.EFI\n\n.PHONY: all clean\n";
